55	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
56	  values.reduce((total, value) => total + amount(value), 0);
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
68	
69	const BLOCK_SIZE = 3;
70	
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const basePremiumForSameTypeItems = (items: Item[]): number =>
74	  items.length === BLOCK_SIZE
75	    ? BLOCK_BASE_PREMIUM
76	    : sumBy(items, itemBasePremium);
77	
78	const sameTypeGroups = (items: Item[]): Item[][] => {
79	  const groupsByType = new Map<string, Item[]>();
80	  for (const item of items) {
81	    const group = groupsByType.get(item.type) ?? [];
82	    group.push(item);
83	    groupsByType.set(item.type, group);
84	  }
85	  return [...groupsByType.values()];
86	};
87	
88	const CURSE_SURCHARGE_RATE = 0.5;
89	
90	const HIGH_ENCHANTMENT_LEVEL = 5;
91	
92	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
93	
94	interface SurchargeRule {
95	  appliesTo: (item: Item) => boolean;
96	  rate: number;
97	}
98	
99	const SURCHARGE_RULES: SurchargeRule[] = [
100	  {
101	    appliesTo: (item) => item.cursed === true,
102	    rate: CURSE_SURCHARGE_RATE,
103	  },
104	  {
105	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
106	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
107	  },
108	];
109	
110	const itemSurchargeRate = (item: Item): number =>
111	  sumBy(
112	    SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)),
113	    (rule) => rule.rate,
114	  );
115	
116	const itemSurcharge = (item: Item): number =>
117	  itemBasePremium(item) * itemSurchargeRate(item);
118	
119	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
120	
121	const PROCESSING_FEE = 5;
122	
123	const LOYALTY_YEARS = 2;
124	
125	const LOYALTY_DISCOUNT_RATE = 0.2;
126	
127	const loyaltyDiscountRate = (customer: Customer): number =>
128	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT_RATE : 0;
129	
130	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
131	
132	const followUpContractDiscountRate = (precedingContracts: number): number =>
133	  precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
134	
135	// Policy-wide modifiers are rates applied to the policy base premium.
136	// Surcharges are positive rates, discounts negative ones.
137	const policyModifierRate = (
138	  customer: Customer,
139	  precedingContracts: number,
140	): number =>
141	  FIRST_INSURANCE_SURCHARGE_RATE +
142	  loyaltyDiscountRate(customer) +
143	  followUpContractDiscountRate(precedingContracts);
144	
145	const quotePremium = (
146	  step: QuoteStep,
147	  customer: Customer,
148	  precedingContracts: number,
149	): number => {
150	  const policyBasePremium = sumBy(
151	    sameTypeGroups(step.items),
152	    basePremiumForSameTypeItems,
153	  );
154	  const itemSurcharges = sumBy(step.items, itemSurcharge);
155	  // Keep this as `base + base * rate`. Factoring it to `base * (1 + rate)`
156	  // introduces IEEE-754 drift that is always upward (e.g. base 180 at rate 0.1
157	  // gives 198.00000000000003 instead of 198), and Math.ceil below turns any
158	  // such drift into a full extra G. Sword + staff would quote 204, not 203.
159	  const policyModifierAmount =
160	    policyBasePremium * policyModifierRate(customer, precedingContracts);
161	  // Rounded in the MHPCO's favour; only the final premium is rounded.
162	  return Math.ceil(
163	    policyBasePremium + itemSurcharges + policyModifierAmount + PROCESSING_FEE,
164	  );
165	};
166	
167	// Deliberately kept separate from BASE_PREMIUM_BY_TYPE. The two tables share a
168	// key domain but not a fact: an item's base premium and its insurance value are
169	// independent numbers the spec states separately. Merging them into one
170	// catalogue would couple them in the reader's mind for no gain.
171	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
172	  sword: 1000,
173	  amulet: 600,
174	  staff: 800,
175	  potion: 400,
176	  rune: 250,
177	  moonstone: 250,
178	};
179	
180	const insuranceValue = (item: Item): number =>
181	  INSURANCE_VALUE_BY_TYPE[item.type];
182	
183	// The block discount affects the premium only, never the insurance sum.
184	const insuranceSum = (policy: QuoteStep): number =>
185	  sumBy(policy.items, insuranceValue);
186	
187	const DEDUCTIBLE = 100;
188	
189	const CAP_MULTIPLE = 2;
190	
191	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
192	
193	const REDUCED_REIMBURSEMENT_RATE = 0.5;
194	
195	const FULL_REIMBURSEMENT_RATE = 1;
196	
197	// Named for the trigger (enchantment level), to keep it distinct from the
198	// premium-side HIGH_ENCHANTMENT_LEVEL, which is a different threshold (5).
199	const reimbursementRate = (item: Item): number =>
200	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
201	    ? REDUCED_REIMBURSEMENT_RATE
202	    : FULL_REIMBURSEMENT_RATE;
203	
204	// The deductible is withheld once per damage entry, not once per incident,
205	// and applies after any reimbursement clause has reduced the amount.
206	// Clamped per entry, not on the total: a damage smaller than the deductible
207	// yields nothing, but must not eat into another damage's reimbursement.
208	const reimbursementForDamage = (damage: Damage, item: Item): number =>
209	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
210	
211	const settleClaim = (step: ClaimStep, policy: QuoteStep): ClaimResult => {
212	  const payout = sumBy(step.incident.damages, (damage) =>
213	    reimbursementForDamage(
214	      damage,
215	      policy.items.find((item) => item.type === damage.itemType) as Item,
216	    ),
217	  );
218	  const cap = insuranceSum(policy) * CAP_MULTIPLE;
219	  return { payout, remainingCap: cap - payout };
220	};
221	
222	// A step's index is exactly the number of contracts concluded before it.
223	export const runScenario = (scenario: Scenario): ScenarioResult => ({
224	  results: scenario.steps.map((step, precedingContracts) =>
225	    step.op === "claim"
226	      ? settleClaim(step, scenario.steps[step.policy] as QuoteStep)
227	      : {
228	          premium: quotePremium(step, scenario.customer, precedingContracts),
229	        },
230	  ),
231	});
