// Which insured item a damage entry refers to. Matching on type alone is
// enough while every test damages a type the policy covers; the pending
// "item not part of the policy" and "more damage entries than covered" cases
// will need this to reject rather than return a match, which is why the
// lookup is named and separate rather than inlined behind a cast.
const insuredItemFor = (damage: Damage, policy: QuoteStep): Item =>
  policy.items.find((item) => item.type === damage.itemType) as Item;

const settleClaim = (step: ClaimStep, policy: QuoteStep): ClaimResult => {
  const payout = sumBy(step.incident.damages, (damage) =>
    reimbursementForDamage(damage, insuredItemFor(damage, policy)),
  );
  const cap = insuranceSum(policy) * CAP_MULTIPLE;
  return { payout, remainingCap: cap - payout };
};
